        private fun concatIntArrays(chunks: List<IntArray>): IntArray {
            var total = 0
            for (chunk in chunks) {
                total += chunk.size
            }
            val result = IntArray(total)
            var offset = 0
            for (chunk in chunks) {
                chunk.copyInto(result, destinationOffset = offset)
                offset += chunk.size
            }
            return result
        }

